t = int(input())
for i in range(t):
	(s, c, k) = map(int, input().split())
	ans = 0
	if s >= k:
		ans = pow(2, s - k + 1) + 1
		if c > s - k:
			ans += pow(2, s - k + 1)
			if k == 1:
				ans += sum((pow(2, r) for r in range(s - k + 2, c + 1)))
	elif k == 1:
		ans += pow(2, c + 1) - 2
	print(ans)
